"""Creates a channel-wise tensor that correctly broadcasts with parameter p."""
if p.dim() == 0:
    return nn.Parameter(torch.tensor(float(init_val), device=p.device, dtype=p.dtype))
else:
    shape = [p.shape[0]] + [1] * (p.dim() - 1)
    return nn.Parameter(torch.full(shape, float(init_val), device=p.device, dtype=p.dtype))
